use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationTokenHashAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationTokenHashAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTokenHash returns null on a freshly created holder.
     */
    public function testTokenHashNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationTokenHashAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTokenHashAssigned());
        $this->assertNull($holder->getTokenHash());
    }
}
class ImplWithUserInvitationTokenHashAttributeHolderUnitTest
